create table if not exists public.platform_capability_registry (id uuid primary key default gen_random_uuid(), capability_key text not null unique, capability_name text not null, domain text not null, criticality text not null check (criticality in ('integral','critical','supporting')), system_of_record text not null, status text not null default 'foundation', description text not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.platform_event_outbox (id uuid primary key default gen_random_uuid(), tenant_id uuid, event_type text not null, aggregate_type text not null, aggregate_id uuid, actor_person_id uuid, payload jsonb not null default '{}'::jsonb, occurred_at timestamptz not null default now(), published_at timestamptz, status text not null default 'pending', attempts integer not null default 0);
create index if not exists platform_event_outbox_pending_idx on public.platform_event_outbox(status, occurred_at);
create table if not exists public.mobile_app_installations (id uuid primary key default gen_random_uuid(), tenant_id uuid, person_id uuid, installation_id text not null unique, platform text not null check(platform in ('ios','android','web')), app_variant text not null default 'ls1', app_version text, os_version text, locale text, timezone text, notifications_enabled boolean not null default false, last_seen_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.mobile_push_tokens (id uuid primary key default gen_random_uuid(), installation_id uuid not null references public.mobile_app_installations(id) on delete cascade, provider text not null check(provider in ('apns','fcm','webpush')), token text not null unique, environment text not null default 'production', active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.public_competition_subscriptions (id uuid primary key default gen_random_uuid(), installation_id uuid not null references public.mobile_app_installations(id) on delete cascade, competition_id uuid not null references public.competitions(id) on delete cascade, athlete_id uuid references public.athletes(id) on delete cascade, team_id uuid, event_id uuid references public.competition_events(id) on delete cascade, subscription_type text not null check(subscription_type in ('competition','athlete','team','event')), active boolean not null default true, created_at timestamptz not null default now(), unique(installation_id,competition_id,subscription_type,athlete_id,event_id));
create table if not exists public.mobile_release_channels (id uuid primary key default gen_random_uuid(), platform text not null check(platform in ('ios','android')), app_variant text not null default 'ls1', channel text not null default 'production', minimum_supported_version text, current_version text, store_url text, status text not null default 'planned', metadata jsonb not null default '{}'::jsonb, updated_at timestamptz not null default now(), unique(platform,app_variant,channel));
create table if not exists public.mobile_live_event_bookmarks (id uuid primary key default gen_random_uuid(), installation_id uuid not null references public.mobile_app_installations(id) on delete cascade, competition_id uuid not null references public.competitions(id) on delete cascade, competition_event_id uuid references public.competition_events(id) on delete cascade, athlete_id uuid references public.athletes(id) on delete cascade, notify_heat_assignment boolean not null default true, notify_start boolean not null default true, notify_result boolean not null default true, created_at timestamptz not null default now(), unique(installation_id,competition_id,competition_event_id,athlete_id));
create table if not exists public.mobile_delivery_receipts (id uuid primary key default gen_random_uuid(), push_token_id uuid references public.mobile_push_tokens(id) on delete set null, notification_event_id uuid, provider_message_id text, status text not null, delivered_at timestamptz, opened_at timestamptz, error_code text, created_at timestamptz not null default now());
create table if not exists public.calendar_event_participants (id uuid primary key default gen_random_uuid(), calendar_event_id uuid not null references public.calendar_events(id) on delete cascade, person_id uuid, athlete_id uuid references public.athletes(id) on delete cascade, team_id uuid, participation_status text not null default 'required', source text not null default 'system', created_at timestamptz not null default now(), unique(calendar_event_id,person_id,athlete_id,team_id));
create table if not exists public.calendar_event_changes (id uuid primary key default gen_random_uuid(), calendar_event_id uuid not null references public.calendar_events(id) on delete cascade, change_type text not null, previous_value jsonb not null default '{}'::jsonb, new_value jsonb not null default '{}'::jsonb, changed_by_person_id uuid, changed_at timestamptz not null default now());
create table if not exists public.registration_requirements (id uuid primary key default gen_random_uuid(), organization_id uuid not null, season_id uuid, program_id uuid, requirement_type text not null, name text not null, required boolean not null default true, governing_body_id uuid, valid_from date, valid_until date, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
create table if not exists public.registration_requirement_status (id uuid primary key default gen_random_uuid(), registration_id uuid not null references public.registrations(id) on delete cascade, requirement_id uuid not null references public.registration_requirements(id) on delete cascade, status text not null default 'pending', satisfied_at timestamptz, evidence_document_id uuid, notes text, unique(registration_id,requirement_id));
create table if not exists public.eligibility_decisions (id uuid primary key default gen_random_uuid(), athlete_id uuid not null references public.athletes(id) on delete cascade, organization_id uuid not null, sport_id uuid, season_id uuid, competition_id uuid references public.competitions(id) on delete cascade, eligibility_type text not null, status text not null, reason text, source_system text not null default 'ls1', source_reference text, effective_at timestamptz not null default now(), expires_at timestamptz, created_at timestamptz not null default now());
create index if not exists eligibility_decisions_athlete_idx on public.eligibility_decisions(athlete_id,effective_at desc);
